import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"充值与提现","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/finance.md","filePath":"zh/guide/finance.md","lastUpdated":1790683574000}'),l={name:"zh/guide/finance.md"};function i(p,a,o,r,d,c){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="充值与提现" tabindex="-1">充值与提现 <a class="header-anchor" href="#充值与提现" aria-label="Permalink to &quot;充值与提现&quot;">​</a></h1><h2 id="充值-入金" tabindex="-1">充值（入金） <a class="header-anchor" href="#充值-入金" aria-label="Permalink to &quot;充值（入金）&quot;">​</a></h2><p>平台支持两套数字资产入金通道，运营可在后台一键切换，<strong>同一时间只有一套生效</strong>。</p><h3 id="用户侧流程" tabindex="-1">用户侧流程 <a class="header-anchor" href="#用户侧流程" aria-label="Permalink to &quot;用户侧流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户进入充值页</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>选择币种与网络（TRC20 / ERC20 / BEP20 等）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>获取专属收款地址（每位用户地址稳定，反复充值无需重新获取）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>用户转账</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>链上确认后系统自动入账</span></span></code></pre></div><h3 id="两套通道的区别" tabindex="-1">两套通道的区别 <a class="header-anchor" href="#两套通道的区别" aria-label="Permalink to &quot;两套通道的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>优盾通道</th><th>TokenPay 通道</th></tr></thead><tbody><tr><td>用户操作</td><td>进入充值页直接看到专属收款地址，转多少到多少</td><td><strong>下单式</strong>：先填金额，系统生成应付币数、收款二维码与有效期倒计时，按额付款</td></tr><tr><td>收款地址</td><td>每位用户专属、长期稳定</td><td>每位用户专属、长期稳定</td></tr><tr><td>到账依据</td><td>链上实际到账</td><td>回调通知里的<strong>链上实收金额</strong>，与填的金额不一致时以实收为准</td></tr><tr><td>适合场景</td><td>用户习惯自由转账</td><td>需要&quot;所见即所付&quot;、减少充错金额的场景</td></tr></tbody></table><p>两套通道在用户端看到的是同一个「充值」入口，用户不需要知道背后是哪一套；运营在后台「第三方配置 → 支付网关」二选一切换，切换后用户端下次进入充值页即生效。</p><div class="warning custom-block"><p class="custom-block-title">切换 TokenPay 前先配好</p><p>「TokenPay 配置」卡片里的服务地址、ApiToken、回调地址必须先填写并启用，再切支付网关。回调地址填错或未填，用户付款后订单会一直停在「审核中」不到账。两张卡片都是<strong>超级管理员专属</strong>，详见<a href="/CoinExchange/zh/guide/site-config#第三方配置">第三方配置</a>。</p></div><div class="tip custom-block"><p class="custom-block-title">自动到账</p><p>充值以<strong>链上实际到账金额</strong>为准自动入账，无需人工审核介入。后台的「充值记录」用于查询与核对，正常情况下不需要运营手工确认。</p></div><h3 id="运营侧要做的事" tabindex="-1">运营侧要做的事 <a class="header-anchor" href="#运营侧要做的事" aria-label="Permalink to &quot;运营侧要做的事&quot;">​</a></h3><ul><li>在「充值通道」中配置开放哪些币种与网络</li><li>在「充值记录」中查询到账情况、处理用户咨询</li><li>通道异常时切换到备用通道</li><li>极少数情况下（如通道回调延迟）订单停在「审核中」，可在「充值管理」核对链上到账后手动通过；正常到账<strong>不需要</strong>运营确认</li></ul><div class="warning custom-block"><p class="custom-block-title">网络务必配对</p><p>币种与网络（链）的对应关系必须配置正确。配错会导致用户往错误的链上转账，<strong>这类资产通常无法找回</strong>。</p></div><h2 id="提现-出金" tabindex="-1">提现（出金） <a class="header-anchor" href="#提现-出金" aria-label="Permalink to &quot;提现（出金）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提交提现申请</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>系统校验：实名等级、提现限额、资金密码</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>后台「提现管理」出现待审核记录</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>运营审核 → 通过（发起链上转账）/ 驳回（原路退回）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>用户端状态更新</span></span></code></pre></div><h3 id="运营侧要点" tabindex="-1">运营侧要点 <a class="header-anchor" href="#运营侧要点" aria-label="Permalink to &quot;运营侧要点&quot;">​</a></h3><ul><li><strong>提现通道</strong>配置决定开放哪些币种与网络</li><li><strong>实名限额</strong>决定不同认证等级的提现额度</li><li>驳回的提现会把冻结的资产退回用户账户</li></ul><div class="danger custom-block"><p class="custom-block-title">审核不可逆</p><p>提现审核通过后会发起真实的链上转账，<strong>一旦发出无法撤回</strong>。审核时请逐项核对：</p><ol><li>提现地址是否与所选网络匹配</li><li>用户账户是否处于异常状态</li><li>提现金额是否与该用户的资产、流水相符（异常大额建议人工复核）</li></ol></div><h2 id="归集" tabindex="-1">归集 <a class="header-anchor" href="#归集" aria-label="Permalink to &quot;归集&quot;">​</a></h2><p>平台收到的充值资金会归集到统一地址。归集记录在后台可查。</p><h2 id="资金流水" tabindex="-1">资金流水 <a class="header-anchor" href="#资金流水" aria-label="Permalink to &quot;资金流水&quot;">​</a></h2><p>所有资金变动（充值、提现、划转、下单、结算、活动奖励、后台调账）都会产生一条流水，记录：</p><ul><li>变动类型</li><li>变动金额</li><li><strong>变动前余额 / 变动后余额</strong></li><li>发生时间</li></ul><p>核账时以流水为准。任何&quot;余额对不上&quot;的问题，第一步都是拉这个用户的完整流水逐条核对。</p>`,24)])])}const g=s(l,[["render",i]]);export{u as __pageData,g as default};
